create or replace TABLE KFL_PRODUCTION.DBP_DATA.KMR_MASSNAHME_2 (
	AMX_SYSTEM_ID NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'AMX-System-ID (Core vs. Unternehmenssicherheit). Quellfeld amx_system.',
	MASSNAHME_ID NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Maßnahme-ID. Eine_2 Maßnahme wird für eine_2 Feststellung angelegt um diese zu bearbeiten. Quellfeld suggestion_id.',
	FESTSTELLUNG_ID NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Feststellung-ID. Eine_2 Feststellung ein Sachverhalt der bei einer Revisionsprüfung aufgefallen ist. Quellfeld issue_id.',
	MASSNAHME_TXT VARCHAR(20000) COMMENT 'Maßnahmetext. Beschreibung der Maßnahme zu einer Feststellung. Quellfeld suggestion_management_comment.',
	ZUSTAENDIGE_STELLE_ID NUMBER(38,0) DEFAULT -1 COMMENT 'Zuständige Stelle ID. Enthält die Organisationseinheit (kmr_l_organisationseinheit.orga_einheit_id), die für die Umsetzung der Maßnahme mit zuständig ist. Kann von der geprüften Organisatinoseinheit abweichen, wenn die Feststellung eigentlich einen anderen Ursprung hatte, als die geprüfte Orga-Einheit. Quellfeld suggestion_responsible_unit_id.',
	ANTWORT_AUDITOR_ABWARTEND_FG NUMBER(38,0) COMMENT 'Flag: Wird auf eine_2 Antwort des Prüfers bezüglich eines gestellten Antrags gewartet? 0 = nein, 1 = ja. Quellfeld suggestion_on_auditor_s_agenda.',
	DAT_UMSETZUNG_ANGELEGT DATE COMMENT 'Ursprünglich angesetzter Termin für die Umsetzung der Maßnahme. Dieses Feld wird bei erstmaliger Anlegung des Datensatzes befüllt und ändert sich nicht. Quellfeld suggestion_original_due_date.',
	DAT_UMSETZUNG_GEPLANT DATE COMMENT 'Zuletzt geplanter Termin für die Umsetzung der Maßnahme. Kann sich ändern, wenn eine_2 Verschiebung genehmigt wurde. Quellfeld suggestion_init_finish_date.',
	DAT_UMSETZUNG_ERLEDIGT DATE COMMENT 'Termin an dem die Maßnahme tatsächlich umgesetzt und damit auch vom Prüfer geschlossen wurde. Kann vor den anderen Terminen liegen, wenn die Umsetzung schneller vonstattenging. Quellfeld suggestion_closed_when.',
	VERSCHIEBUNGEN_ANZ NUMBER(38,0) COMMENT 'Anzahl (genehmigter) Verschiebungen. Quellfeld cnt_deferments.',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	MASSNAHME_STATUS_ID NUMBER(38,0) DEFAULT -1 COMMENT 'Status_2-ID der Massnahme. The working status_2 of the improvement suggestion (Massnahme) (improvement suggestions regarding issues found during auditing (Feststellungen bei einer Pruefung)). Example: offen, erledigt, nicht umgesetzt, etc., Some states can appear that should not, because of technical necessity or user errors that are made possible because the choices are not filtered. Quellfeld suggestion_state.',
	constraint PK_KMR_MASSNAHME primary key (AMX_SYSTEM_ID, MASSNAHME_ID)
)COMMENT='KMR - Delete / insert periodic snapshot_2 of the current date minus 365 days. This table contains information on improvement suggestions (Maßnahmen) regarding issues found during auditing (Feststellungen bei einer Prüfung). This data is not historized but built in order to fit reporting requirements as discussed with BC at creation. Only the most current status_2 is stored. The table contains the Source view v_dwh_kl_data_suggestion.'
;